package com.amalaei.engineering;

import android.app.*;import android.os.Bundle;import android.graphics.Color;import android.widget.*;import org.json.*;import java.time.*;import java.util.*;import java.math.*;

public final class ReportsActivity extends Activity {
    Store store;LinearLayout body;android.graphics.Typeface font;int period=0;
    public void onCreate(Bundle state){super.onCreate(state);font=android.graphics.Typeface.createFromAsset(getAssets(),"fonts/Cairo.ttf");store=new Store(this);show();}
    protected void onDestroy(){store.close();super.onDestroy();}
    void show(){ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(28,42,28,28);body.setBackgroundColor(0xfff6f7fb);scroll.addView(body);setContentView(scroll);text("التقارير والإحصاءات",25);Spinner choices=new Spinner(this);choices.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"هذا الشهر","الشهر الماضي","آخر 90 يومًا","كل البيانات"}));choices.setSelection(period);body.addView(choices);choices.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int n,long id){if(period!=n){period=n;show();}}});
        long[] range=range();ArrayList<JSONObject> leads=store.query("SELECT * FROM leads WHERE business=?",AppMode.MODE),events=store.query("SELECT * FROM events"),ledger=store.query("SELECT * FROM ledgerEntries"),quoteRows=store.query("SELECT * FROM quotes");int added=ReportMath.countNew(leads,events,range[0],range[1]);int complete=ReportMath.closed(leads,true),lost=ReportMath.closed(leads,false);BigDecimal net=ReportMath.ledgerNet(ledger,range[0],range[1]);BigDecimal accepted=BigDecimal.ZERO;for(JSONObject row:quoteRows)try{JSONObject q=new JSONObject(row.getString("data"));if(QuoteStatus.ACCEPTED.equals(QuoteStatus.value(q)))accepted=accepted.add(Quotation.subtotal(q).add(QuoteMath.tax(Quotation.subtotal(q))));}catch(Exception ignored){}
        int salesComplete=0,salesLost=0,serviceComplete=0,serviceLost=0;for(JSONObject lead:leads){boolean sales=!lead.optString("business").equals("survey")||lead.optString("requestType","sales").equals("sales");if(lead.optInt("stage")==4){if(sales)salesComplete++;else serviceComplete++;}if(lead.optInt("stage")==5){if(sales)salesLost++;else serviceLost++;} }
        card("عملاء جدد",String.valueOf(added));card("مكتمل / مغلق",complete+" / "+lost);card("نسبة التحويل للمبيعات",Math.round((salesComplete*100.0)/Math.max(1,salesComplete+salesLost))+"%");card("نسبة الإنجاز للخدمات",Math.round((serviceComplete*100.0)/Math.max(1,serviceComplete+serviceLost))+"%");card("قيمة العروض المقبولة",QuoteMath.money(accepted)+" ر.س");card("صافي الدفتر للفترة",LedgerMath.money(net));button("رجوع",this::finish);
    }
    long[] range(){ZoneId zone=ZoneId.systemDefault();LocalDate today=LocalDate.now();LocalDate start;LocalDate end;if(period==0){start=today.withDayOfMonth(1);end=start.plusMonths(1);}else if(period==1){end=today.withDayOfMonth(1);start=end.minusMonths(1);}else if(period==2){start=today.minusDays(89);end=today.plusDays(1);}else{return new long[]{0,Long.MAX_VALUE};}return new long[]{start.atStartOfDay(zone).toInstant().toEpochMilli(),end.atStartOfDay(zone).toInstant().toEpochMilli()};}
    void text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTypeface(font);t.setTextColor(0xff102a43);t.setPadding(0,10,0,10);body.addView(t);}void card(String label,String value){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(22,15,22,15);c.setBackgroundColor(Color.WHITE);TextView a=new TextView(this);a.setText(label);a.setTypeface(font);a.setTextColor(0xff627487);TextView b=new TextView(this);b.setText(value);b.setTextSize(23);b.setTypeface(font);b.setTextColor(0xff0f766e);c.addView(a);c.addView(b);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,8,0,8);body.addView(c,p);}void button(String label,Runnable action){Button b=new Button(this);b.setText(label);b.setTypeface(font);body.addView(b);b.setOnClickListener(v->action.run());}
}
